    { const char * tb_v321 = "        if (++tb_vcol == 80) { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v321; }
    { const char * tb_v322 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v322; }
    { const char * tb_v323 = "    if (tb_vrow == 25) {\n"; *(const char * *)tb_grow(v_lines) = tb_v323; }
    { const char * tb_v324 = "        for (int i = 0; i < 24 * 80; i++) tb_vga[i] = tb_vga[i + 80];\n"; *(const char * *)tb_grow(v_lines) = tb_v324; }
    { const char * tb_v325 = "        for (int i = 24 * 80; i < 25 * 80; i++) tb_vga[i] = (unsigned short)(tb_vcolor << 8 | ' ');\n"; *(const char * *)tb_grow(v_lines) = tb_v325; }
