    { const char * tb_v1159 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1159; }
    { const char * tb_v1160 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1160; }
    { const char * tb_v1161 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1161; }
