    { const char * tb_v1203 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1203; }
    { const char * tb_v1204 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v1204; }
    { const char * tb_v1205 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v1205; }
    { const char * tb_v1206 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v1206; }
    { const char * tb_v1207 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1207; }
    { const char * tb_v1208 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1208; }
    { const char * tb_v1209 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v1209; }
    { const char * tb_v1210 = "        m = \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1210; }
    { const char * tb_v1211 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v1211; }
    { const char * tb_v1212 = "        m = \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1212; }
    { const char * tb_v1213 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1213; }
    { const char * tb_v1214 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1214; }
    { const char * tb_v1215 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1215; }
    { const char * tb_v1216 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1216; }
    { const char * tb_v1217 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1217; }
    { const char * tb_v1218 = "TB_API void tb_guard_thread(char *here, long long lim) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1218; }
    { const char * tb_v1219 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v1219; }
    { const char * tb_v1220 = "    ss.ss_sp = malloc(65536); ss.ss_size = 65536; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1220; }
