    { const char * tb_v2622 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2622; }
    { const char * tb_v2623 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v2623; }
    { const char * tb_v2624 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v2624; }
    { const char * tb_v2625 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v2625; }
    { const char * tb_v2626 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v2626; }
    { const char * tb_v2627 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2627; }
    { const char * tb_v2628 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2628; }
    { const char * tb_v2629 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v2629; }
    { const char * tb_v2630 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v2630; }
    { const char * tb_v2631 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2631; }
    { const char * tb_v2632 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2632; }
    { const char * tb_v2633 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2633; }
    { const char * tb_v2634 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2634; }
    { const char * tb_v2635 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2635; }
    { const char * tb_v2636 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2636; }
    { const char * tb_v2637 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2637; }
    { const char * tb_v2638 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2638; }
    { const char * tb_v2639 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2639; }
    { const char * tb_v2640 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2640; }
    { const char * tb_v2641 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2641; }
    { const char * tb_v2642 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2642; }
    { const char * tb_v2643 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2643; }
    { const char * tb_v2644 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2644; }
    { const char * tb_v2645 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2645; }
    { const char * tb_v2646 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2646; }
    { const char * tb_v2647 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2647; }
    { const char * tb_v2648 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2648; }
    { const char * tb_v2649 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2649; }
    { const char * tb_v2650 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2650; }
    { const char * tb_v2651 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2651; }
    { const char * tb_v2652 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2652; }
    { const char * tb_v2653 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2653; }
    { const char * tb_v2654 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2654; }
    { const char * tb_v2655 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2655; }
    { const char * tb_v2656 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2656; }
    { const char * tb_v2657 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2657; }
    { const char * tb_v2658 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2658; }
    { const char * tb_v2659 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2659; }
    { const char * tb_v2660 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2660; }
    { const char * tb_v2661 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2661; }
    { const char * tb_v2662 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2662; }
    { const char * tb_v2663 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2663; }
    { const char * tb_v2664 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v2664; }
    { const char * tb_v2665 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2665; }
    { const char * tb_v2666 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2666; }
    { const char * tb_v2667 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v2667; }
    { const char * tb_v2668 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2668; }
    { const char * tb_v2669 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2669; }
    { const char * tb_v2670 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2670; }
    { const char * tb_v2671 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2671; }
    { const char * tb_v2672 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2672; }
    { const char * tb_v2673 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2673; }
