    { const char * tb_v2722 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2722; }
    { const char * tb_v2723 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v2723; }
    { const char * tb_v2724 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v2724; }
