    { const char * tb_v2856 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
    { const char * tb_v2857 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2857; }
    { const char * tb_v2858 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2858; }
