    { const char * tb_v3010 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v3010; }
    { const char * tb_v3011 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v3011; }
    { const char * tb_v3012 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3012; }
    { const char * tb_v3013 = "    uint32_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v3013; }
    { const char * tb_v3014 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) { tb_irq_restore(f); tb_yield(); f = tb_irq_save(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3014; }
