    { const char * tb_v3455 = "    if (!ok || z.n < (stride + 1) * h) { free(z.out); *why = \"PNG испорчен\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3455; }
    { const char * tb_v3456 = "    uint32_t *px = malloc((size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3456; }
    { const char * tb_v3457 = "    if (!px) { free(z.out); *why = \"не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3457; }
    { const char * tb_v3458 = "    unsigned char *prev = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3458; }
