    { const char * tb_v3461 = "        for (size_t i = 0; i < stride; i++) {   // фильтры строк PNG\n"; *(const char * *)tb_grow(v_lines) = tb_v3461; }
    { const char * tb_v3462 = "            int a = i >= bpp ? r[i - bpp] : 0, b = prev ? prev[i] : 0, c = prev && i >= bpp ? prev[i - bpp] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3462; }
