    { const char * tb_v3475 = "                    raw[k] = v; s[k] = ctype == 3 ? v : v * 255 / ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3475; }
    { const char * tb_v3476 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v3476; }
