    { const char * tb_v3489 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v3489; }
    { const char * tb_v3490 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v3490; }
    { const char * tb_v3491 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3491; }
    { const char * tb_v3492 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3492; }
    { const char * tb_v3493 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3493; }
    { const char * tb_v3494 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3494; }
    { const char * tb_v3495 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3495; }
    { const char * tb_v3496 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3496; }
    { const char * tb_v3497 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3497; }
    { const char * tb_v3498 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v3498; }
    { const char * tb_v3499 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3499; }
    { const char * tb_v3500 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3500; }
    { const char * tb_v3501 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3501; }
    { const char * tb_v3502 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3502; }
    { const char * tb_v3503 = "    uint32_t *px = tb_png(d, (size_t)sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v3503; }
    { const char * tb_v3504 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3504; }
    { const char * tb_v3505 = "    if (!px) { tb_err = why; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3505; }
    { const char * tb_v3506 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3506; }
    { const char * tb_v3507 = "    if (need > 0xFFFFFFFFu) { free(px); tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3507; }
    { const char * tb_v3508 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3508; }
    { const char * tb_v3509 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v3509; }
    { const char * tb_v3510 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v3510; }
    { const char * tb_v3511 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v3511; }
    { const char * tb_v3512 = "    if (!all || !list) { free(px); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3512; }
    { const char * tb_v3513 = "    memcpy(tb_imgpx + tb_imgpx_n, px, (size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3513; }
