    { const char * tb_v3617 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
