    { const char * tb_v5288 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5288; }
    { const char * tb_v5289 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5289; }
    { const char * tb_v5290 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5290; }
    { const char * tb_v5291 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v5291; }
    { const char * tb_v5292 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5292; }
    { const char * tb_v5293 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5293; }
    { const char * tb_v5294 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5294; }
    { const char * tb_v5295 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5295; }
    { const char * tb_v5296 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5296; }
    { const char * tb_v5297 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5297; }
    { const char * tb_v5298 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5298; }
    { const char * tb_v5299 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5299; }
    { const char * tb_v5300 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5300; }
    { const char * tb_v5301 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5301; }
    { const char * tb_v5302 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v5302; }
    { const char * tb_v5303 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5303; }
    { const char * tb_v5304 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5304; }
    { const char * tb_v5305 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v5305; }
    { const char * tb_v5306 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v5306; }
    { const char * tb_v5307 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v5307; }
    { const char * tb_v5308 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v5308; }
    { const char * tb_v5309 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5309; }
    { const char * tb_v5310 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5310; }
    { const char * tb_v5311 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5311; }
    { const char * tb_v5312 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5312; }
    { const char * tb_v5313 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5313; }
    { const char * tb_v5314 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v5314; }
    { const char * tb_v5315 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v5315; }
    { const char * tb_v5316 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v5316; }
    { const char * tb_v5317 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v5317; }
    { const char * tb_v5318 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5318; }
    { const char * tb_v5319 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5319; }
    { const char * tb_v5320 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5320; }
    { const char * tb_v5321 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5321; }
    { const char * tb_v5322 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5322; }
    { const char * tb_v5323 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5323; }
    { const char * tb_v5324 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v5324; }
    { const char * tb_v5325 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v5325; }
    { const char * tb_v5326 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5326; }
    { const char * tb_v5327 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5327; }
    { const char * tb_v5328 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5328; }
    { const char * tb_v5329 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5329; }
    { const char * tb_v5330 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v5330; }
    { const char * tb_v5331 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v5331; }
    { const char * tb_v5332 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v5332; }
    { const char * tb_v5333 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5333; }
    { const char * tb_v5334 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5334; }
    { const char * tb_v5335 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v5335; }
    { const char * tb_v5336 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5336; }
    { const char * tb_v5337 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5337; }
    { const char * tb_v5338 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5338; }
    { const char * tb_v5339 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5339; }
    { const char * tb_v5340 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5340; }
    { const char * tb_v5341 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5341; }
    { const char * tb_v5342 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5342; }
    { const char * tb_v5343 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5343; }
    { const char * tb_v5344 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5344; }
    { const char * tb_v5345 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5345; }
    { const char * tb_v5346 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5346; }
    { const char * tb_v5347 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5347; }
    { const char * tb_v5348 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5348; }
    { const char * tb_v5349 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5349; }
    { const char * tb_v5350 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5350; }
    { const char * tb_v5351 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5351; }
    { const char * tb_v5352 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5352; }
    { const char * tb_v5353 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5353; }
    { const char * tb_v5354 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5354; }
    { const char * tb_v5355 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v5355; }
    { const char * tb_v5356 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5356; }
    { const char * tb_v5357 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v5357; }
    { const char * tb_v5358 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5358; }
    { const char * tb_v5359 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5359; }
    { const char * tb_v5360 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5360; }
    { const char * tb_v5361 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5361; }
    { const char * tb_v5362 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5362; }
    { const char * tb_v5363 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5363; }
    { const char * tb_v5364 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5364; }
    { const char * tb_v5365 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5365; }
    { const char * tb_v5366 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v5366; }
    { const char * tb_v5367 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5367; }
    { const char * tb_v5368 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v5368; }
    { const char * tb_v5369 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5369; }
    { const char * tb_v5370 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v5370; }
    { const char * tb_v5371 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v5371; }
    { const char * tb_v5372 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5372; }
    { const char * tb_v5373 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5373; }
    { const char * tb_v5374 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5374; }
    { const char * tb_v5375 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5375; }
    { const char * tb_v5376 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v5376; }
    { const char * tb_v5377 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5377; }
    { const char * tb_v5378 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v5378; }
    { const char * tb_v5379 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v5379; }
    { const char * tb_v5380 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v5380; }
    { const char * tb_v5381 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v5381; }
    { const char * tb_v5382 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v5382; }
    { const char * tb_v5383 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5383; }
    { const char * tb_v5384 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v5384; }
    { const char * tb_v5385 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5385; }
    { const char * tb_v5386 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5386; }
